var numbers2 = Filter(numbers, number => number % 2 == 0);
foreach (var number in numbers2)
{
    Console.WriteLine(number);
}

var numbers3 = Filter(numbers, number => number > 5);
foreach (var number in numbers3)
{
    Console.WriteLine(number);
